        self.configure(bg=THEME['bg'])
        self.minsize(580, 400)

        self.setup_ui()
        self.log("[Loop OS Native] Ventana '✦ UI CONNECT (PC) — Shine OS Component 2 Manager ✦' inicializada (XUI Direct-to-Vulkan Ultra-Low Latency 240Hz (<0.2ms)).", 'success')

