        self.c_hdr = tk.Canvas(self, height=52, bg=THEME['card_bg'], highlightthickness=0)
        self.c_hdr.pack(fill='x', side='top')
        self.c_hdr.create_text(20, 26, text="✦ UI CONNECT (PC) — Shine OS Component 2 Manager ✦", anchor='w', fill=THEME['primary'], font=('Helvetica', 13, 'bold'))
        self.c_hdr.create_rectangle(740, 13, 960, 39, fill=THEME['accent'], outline='', tags='hdr_badge_bg')
        self.c_hdr.create_text(850, 26, text="XUI • 240 FPS Direct", fill='#0b0f19', font=('Helvetica', 9, 'bold'), tags='hdr_badge_txt')
        def _on_hdr_resize(e):
            w = e.width
            self.c_hdr.coords('hdr_badge_bg', w - 210, 13, w - 16, 39)
            self.c_hdr.coords('hdr_badge_txt', w - 113, 26)
        self.c_hdr.bind('<Configure>', _on_hdr_resize)

